package br.com.mikael.nexustech.registry;
import br.com.mikael.nexustech.item.ModItemBlock;import br.com.mikael.nexustech.util.Reference;import net.minecraft.block.Block;import net.minecraftforge.event.RegistryEvent;import net.minecraftforge.fml.common.Mod;import net.minecraftforge.fml.common.eventhandler.SubscribeEvent;
@Mod.EventBusSubscriber(modid=Reference.MOD_ID) public final class RegistryHandler{private RegistryHandler(){}@SubscribeEvent public static void blocks(RegistryEvent.Register<Block> e){e.getRegistry().registerAll(ModBlocks.BLOCKS);}@SubscribeEvent public static void items(RegistryEvent.Register<net.minecraft.item.Item> e){for(Block b:ModBlocks.BLOCKS){ModItemBlock i=new ModItemBlock(b);i.setRegistryName(b.getRegistryName());e.getRegistry().register(i);}}}